      ex: { prompt: 'Write percentile(values, p) using the nearest-rank method: sort ascending, rank = ceil(p / 100 × n), return the value at position rank − 1 (at least 0). Return null for an empty list.', fn: 'percentile', params: 'values, p', cases: [{ args: [[120, 80, 300, 95, 110, 2000, 105, 90, 100, 130], 95], expect: 2000 }, { args: [[120, 80, 300, 95, 110, 2000, 105, 90, 100, 130], 50], expect: 105 }, { args: [[], 95], expect: null }, { args: [[7], 99], expect: 7 }], solution: `function percentile(v,p){if(!v.length)return null;const s=[...v].sort((a,b)=>a-b);const r=Math.ceil(p/100*s.length);return s[Math.max(0,r-1)]}`, hint: 'Sort numerically; nearest rank uses ceil.' },
